public ElementInfo(ElementInfo parent, Map<String, String> namespaces) {
    this.parent = parent;
    if (namespaces.isEmpty()) {
        this.namespaces = Collections.emptyMap();
    } else {
        this.namespaces = new HashMap<>(namespaces);
    }
}
